package tools;

import java.io.File;

import junit.framework.Assert;
import util.test.IOReadGaussianTest;
import views.FrameApp;
import controller.globalCommands.ReadGaussianCommand;

public class Utils {
	/**
	 * Compare file result .xml to mesomery generated by .com.test file
	 * @param app
	 * @param name : file name root (filename.xml / filename.com.test)
	 */
	public static void compareMesomeryXML(FrameApp app, String name) {	
		TestOut.println("Vérifie que les poids de la mesomerie soient corrects (ie correspondent au contenu fichier xml). Fichier : " + name);
		if (! app.menuBar.getItemMethod("HLCI").isSelected())
			TestOut.println("WARNING : HLCI NOT Tested ! ");
		if (! app.menuBar.getItemMethod("HLP").isSelected())
			TestOut.println("WARNING : HLP NOT Tested ! ");
			
		new XMLCompareToMesomery(app.getCurrentMesomery(),  "./test/datas/txml/" + name + ".txml").execute();
	
	}
	
	
	/**
	 * 
	 * @param app
	 * @param name : file name root (filename.xml / filename.com.test)
	 */
	public static void openGaussianAndCompareToXML (final FrameApp app, final String name) {
		try {
			new ReadGaussianCommand(app, new IOReadGaussianTest(new File("./test/datas/test/" + name + ".com.test")) ).execute();
		} catch (Exception e1) {
			e1.printStackTrace();
			TestOut.println ("TEST FAILED !!! Cannot open file : "+name);
			Assert.fail();

		}
		compareMesomeryXML(app, name); 
		
	}
}
